      "type": "tool",
      "name": "path",
      "output_key": "path",
      "tool": "candlesticks",
      "args": {
        "symbol": "{{question}}",
        "hours_back": 0.75,
        "timeframe": "1Min"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "tape",
      "output_key": "tape",
      "tool": "recent_trades",
      "args": {
        "symbol": "{{question}}",
        "minutes_back": 5,
        "limit": 20
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "day",
      "output_key": "day",
      "tool": "daily_context",
      "args": {
        "symbol": "{{question}}"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "story",
      "output_key": "story",
      "tool": "the_story",
      "args": {},
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "market",
      "output_key": "market",
      "tool": "market_tape",
      "args": {
        "symbol": "SPY"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "summary",
      "output_key": "summary",
      "tool": "state_summary",
      "args": {
        "symbol": "{{question}}"
      },
      "fail_ok": true
    },
    {
      "type": "prompt",
      "name": "predict",
      "output_key": "forecast",
      "prompt": "Symbol: {{question}}\nSituation: {{summary.summary}}\nThe story, as it broke: {{news}}\nStory detail: {{story}}\nSession: {{context}}\nLast bar: {{quote}}\nThe day so far: {{day}}\nSPY: {{market}}\nMinute bars, last 45m: {{path}}\nRecent prints: {{tape}}",
      "tools": [],
      "max_tool_iterations": 6,
      "questions": {
        "move": {
          "type": "score",
          "instructions": "How many basis points the price moves over the next five minutes, from the last complete minute close shown. Positive is up. A headline the market has already read leaves the price within a few basis points either way.",
          "criteria": [
            "down 100 basis points or more",
            "down 40 to 100 basis points",
            "down 10 to 40 basis points",
            "unchanged, within 10 basis points either way",
            "up 10 to 40 basis points",
            "up 40 to 100 basis points",
            "up 100 basis points or more"
          ],
          "values": [
            -60,
            -25,
            -8,
            0,
            8,
            25,
            60
          ]
        }
      },
      "answers": {
        "delta_bps": {
          "from": "move",
          "as": "mean"
        },
        "half_width_bps": {
          "from": "move",
          "as": "half_range",
          "coverage": 0.6,
          "min": 2
        },
        "confidence": {
          "from": "move",
          "as": "confidence"
        },
        "driver": {
          "as": "const",
          "value": "the expectation of the move distribution"
        },
        "falsifier": {
          "as": "const",
          "value": "a print outside the quoted band before five minutes are up"
        }
      }
    }
  ]
}

